///|
test "independent common Graph match control is already checked" {
  let program = @program.parse(
    (
      #|{"version":"actql/0.1","id":"fixture.graph_match","stages":[{"id":"main","inputs":{},"steps":[{"values":{"schema":{"node_key":{"type":"number","nullable":false},"p":{"type":"number","nullable":false}},"rows":[{"node_key":1,"p":7}]},"as":"n"},{"graph":{"version":"actql-graph-constructor/0.1","nodes":[{"name":"N","from":"n","key":["node_key"],"labels":[{"name":"Person","properties":{"mode":"columns","columns":[{"from":"p","to":"p"}]}}]}],"edges":[]},"as":"g"},{"from":"g","match_nodes":{"definition":"N","label":"Person","where":{"gt":[{"field":"p"},{"literal":5}]},"fields":["p"]},"as":"selected"}],"results":{"out":{"from":"selected","fields":["p"]}}}],"results":{"answer":{"from":{"stage":"main","result":"out"}}}}
    ),
    construction_limits().program,
    format=Json,
  ).unwrap()
  match
    @check.check_parsed_with_evidence(
      program,
      graph_rows_environment(),
      None,
      [],
      graph_rows_check_limits(),
    ) {
    Checked(_) => ()
    Rejected(diagnostic) => graph_rows_rejected(diagnostic)
    NeedsInputs(_) => fail("The common control has no external input")
  }
}

///|
test "named Graph match has an independently authored complete Program" {
  let actual = compile_with_set(
    "DATA n = SELECT 1 AS node_key, 7 AS p; DATA g = PROPERTY GRAPH (NODE TABLES (n AS N KEY (node_key) LABEL Person PROPERTIES (p))); FROM g |> match_nodes(definition: 'N', label: 'Person', where: {gt: [{field: 'p'}, {literal: 5}]}, fields: ['p']) |> SELECT p",
  )
  let expected = @program.parse(
    (
      #|{"version":"actql/0.1","id":"fixture.query_pair","stages":[{"id":"main","inputs":{},"steps":[{"values":{"schema":{"aql_source_free_unit":{"type":"boolean","nullable":false}},"rows":[{"aql_source_free_unit":true}]},"as":"aql_script_seed_1"},{"from":"aql_script_seed_1","derive":{"aql_query_expr_0":{"literal":1},"aql_query_expr_1":{"literal":7}}},{"select":[{"node_key":"aql_query_expr_0"},{"p":"aql_query_expr_1"}],"as":"aql_data_0"},{"graph":{"version":"actql-graph-constructor/0.1","nodes":[{"name":"N","from":"aql_data_0","key":["node_key"],"labels":[{"name":"Person","properties":{"mode":"columns","columns":[{"from":"p","to":"p"}]}}]}],"edges":[]},"as":"aql_data_2"},{"from":"aql_data_2","match_nodes":{"definition":"N","label":"Person","where":{"gt":[{"field":"p"},{"literal":5}]},"fields":["p"]},"as":"aql_sga_3"},{"from":"aql_sga_3","select":["p"],"as":"aql_script_result"}],"results":{"rows":{"from":"aql_script_result","fields":["p"]}}}],"results":{"answer":{"from":{"stage":"main","result":"rows"}}}}
    ),
    construction_limits().program,
    format=Json,
  ).unwrap()
  assert_eq(semantic(actual), semantic(expected))
  match
    @check.check_parsed_with_evidence(
      actual,
      graph_rows_environment(),
      None,
      [],
      graph_rows_check_limits(),
    ) {
    Checked(_) => ()
    Rejected(diagnostic) => graph_rows_rejected(diagnostic)
    NeedsInputs(_) => fail("A named Graph match does not acquire input")
  }
}

///|
test "named Graph match carries projection order and identity roles to the common owner" {
  for
    suffix in [
      "FROM g |> match_nodes(definition: 'n', bindings: {identity: 'element'}, where: {literal: true}, fields: ['name', 'element']) |> SELECT name, element |> ORDER BY name",
      "DATA selected = FROM g |> normalize_graph() |> match_edges(definition: 'E', label: 'r', bindings: {identity: 'edge', source: 'source', target: 'target'}, fields: ['target', 'edge', 'source']); FROM selected |> SELECT target, edge, source",
    ] {
    let actual = compile_with_set(graph_rows_prefix() + suffix)
    match
      @check.check_parsed_with_evidence(
        actual,
        graph_rows_environment(),
        None,
        [],
        graph_rows_check_limits(),
      ) {
      Checked(_) => ()
      Rejected(diagnostic) => graph_rows_rejected(diagnostic)
      NeedsInputs(_) => fail("A matched Relation reuses its Graph producer")
    }
  }
}

///|
test "named Graph match retains malformed authored contracts for common refusal" {
  for
    call in [
      "match_nodes(definition: 'N', where: {literal: true}, fields: ['missing'])",
      "match_nodes(definition: 'missing', where: {literal: true}, fields: ['name'])",
      "match_nodes(definition: 'N', label: 'missing', where: {literal: true}, fields: ['name'])",
      "match_nodes(definition: 'N', fields: ['name'])", "match_nodes(definition: 'N', where: {literal: 1}, fields: ['name'])",
      "match_nodes(definition: 'N', where: {literal: true}, fields: ['name', 'name'])",
      "match_nodes(definition: 'N', bindings: {identity: 'name'}, where: {literal: true}, fields: ['name'])",
      "match_nodes(definition: 'N', where: {literal: true}, fields: ['name'], extra: true)",
      "match_edges(definition: 'E', bindings: {source: 'src'}, fields: ['src'], types: [1])",
    ] {
    let actual = compile_with_set(graph_rows_prefix() + "FROM g |> " + call)
    assert_true(
      @check.check_parsed_with_evidence(
        actual,
        graph_rows_environment(),
        None,
        [],
        graph_rows_check_limits(),
      )
      is Rejected(_),
      msg=call,
    )
  }
}

///|
test "named Graph match refuses undefined output shape and subsequent Graph calls" {
  for
    suffix in [
      "FROM g |> match_nodes(definition: 'N', where: {literal: true})", "FROM g |> match_nodes(definition: 'N', where: {literal: true}, fields: [])",
      "FROM g |> match_nodes(definition: 'N', where: {literal: true}, fields: ['name', 1])",
      "FROM g |> match_nodes(definition: 'N', where: {literal: true}, fields: ['name']) |> node_rows()",
      "FROM n |> match_nodes(definition: 'N', where: {literal: true}, fields: ['name'])",
    ] {
    let parsed = @query.parse_query_script(
      graph_rows_prefix() + suffix,
      syntax_limits(),
    ).unwrap()
    let actual = compile_query_script(
      parsed,
      { ..fixture_context(), inputs: [], },
      construction_limits(),
    )
    if suffix.has_prefix("FROM n") || suffix.has_suffix("|> node_rows()") {
      assert_true(actual is Err(InvalidQuery), msg=suffix)
    } else {
      assert_true(actual is Err(UnsupportedGraph), msg=suffix)
    }
  }
}

///|
test "SGA DATA normalize lowers once and retains the existing Graph producer" {
  // This is an independently authored ordinary Program. Its only additional
  // step is the existing normalize_graph operation: no Values copy, Result
  // boundary, separate task, source acquisition or local-placement request.
  let expected = @program.parse(
    (
      #|{"version":"actql/0.1","id":"fixture.query_pair","stages":[{"id":"main","inputs":{},"steps":[{"values":{"schema":{"aql_source_free_unit":{"type":"boolean","nullable":false}},"rows":[{"aql_source_free_unit":true}]},"as":"aql_script_seed_1"},{"from":"aql_script_seed_1","derive":{"aql_query_expr_0":{"literal":1}}},{"select":[{"id":"aql_query_expr_0"}],"as":"aql_data_0"},{"graph":{"version":"actql-graph-constructor/0.1","nodes":[{"name":"N","from":"aql_data_0","key":["id"],"labels":[{"name":"Node","properties":{"mode":"columns","columns":[{"from":"id","to":"id"}]}}]}],"edges":[]},"as":"aql_data_2"},{"from":"aql_data_2","normalize_graph":true,"as":"aql_sga_4"},{"from":"aql_sga_4","match_nodes":{"definition":"N","where":{"literal":true},"bindings":{"identity":"aql_keyed_identity_1"},"fields":["aql_keyed_identity_1","id"],"label":"Node"},"as":"aql_keyed_seeds_5"},{"from":"aql_keyed_seeds_5","select":["id"],"as":"aql_script_result"}],"results":{"rows":{"from":"aql_script_result","fields":["id"]}}}],"results":{"answer":{"from":{"stage":"main","result":"rows"}}}}
    ),
    construction_limits().program,
    format=Json,
  ).unwrap()
  let source = "DATA n = SELECT 1 AS id; DATA g = PROPERTY GRAPH (NODE TABLES (n AS N KEY (id) LABEL Node PROPERTIES (id))); DATA normalized = FROM g |> normalize_graph(); FROM GRAPH normalized |> MATCH WALK (a:Node) |> SELECT a.id"
  let actual = compile_with_set(source)
  assert_eq(semantic(actual), semantic(expected))
  assert_eq(@program.stage_count(actual), 1)
  assert_eq(@program.export_count(actual), 1)
  // Lowering evidence only: common-owner admission and public execution
  // are deliberately tested at separate boundaries after the formal handoff.
}

///|
test "SGA normalize can precede MATCH without a synthesized DATA or Result" {
  let source = "DATA n = SELECT 1 AS id; DATA g = PROPERTY GRAPH (NODE TABLES (n AS N KEY (id) LABEL Node PROPERTIES (id))); FROM GRAPH g |> normalize_graph() |> MATCH WALK (a:Node) |> SELECT a.id"
  let actual = semantic(compile_with_set(source))
  assert_true(actual.contains("\"normalize_graph\":true"))
  assert_true(actual.contains("\"as\":\"aql_sga_3\""))
  assert_true(actual.contains("\"from\":\"aql_sga_3\""))
  assert_false(actual.contains("aql_retained_result"))
}

///|
test "SGA graph alias reuse never introduces a Values copy or reacquisition" {
  let source = "DATA n = SELECT 1 AS id; DATA g = PROPERTY GRAPH (NODE TABLES (n AS N KEY (id) LABEL Node PROPERTIES (id))); DATA copied = FROM g; FROM GRAPH copied |> MATCH WALK (a:Node) |> SELECT a.id"
  let actual = semantic(compile_with_set(source))
  assert_true(actual.contains("\"from\":\"aql_data_2\",\"match_nodes\""))
  assert_false(actual.contains("normalize_graph"))
  assert_eq(@program.export_count(compile_with_set(source)), 1)
}

///|
test "SGA script rejects unknown references unconnected consumers and extra input arguments" {
  let prefix = "DATA n = SELECT 1 AS id; DATA g = PROPERTY GRAPH (NODE TABLES (n AS N KEY (id) LABEL Node PROPERTIES (id))); "
  for
    suffix in [
      "DATA normalized = FROM g |> normalize_graph(with: 'g'); FROM GRAPH normalized |> MATCH WALK (a:Node) |> SELECT a.id",
      "DATA normalized = FROM g |> normalize_graph(extra: true); FROM GRAPH normalized |> MATCH WALK (a:Node) |> SELECT a.id",
      "DATA normalized = FROM g |> normalize_graph() |> SELECT id; FROM normalized |> SELECT id",
      "FROM n |> normalize_graph() |> SELECT id",
    ] {
    let script = match
      @query.parse_query_script(prefix + suffix, syntax_limits()) {
      Ok(script) => script
      Err(issue) => fail(suffix + " : " + @debug.to_string(issue.issue))
    }
    assert_true(
      compile_query_script(
        script,
        { ..fixture_context(), inputs: [], },
        construction_limits(),
      )
      is Err(UnsupportedGraph),
      msg=suffix,
    )
  }
  // The original mean fixture is malformed independently of its unconnected
  // source consumer: weights, support and properties are all required.
  let incomplete_mean = @query.parse_query_script(
    prefix +
    "DATA combined = mean_graphs(with: [g, g]); FROM GRAPH combined |> MATCH WALK (a:Node) |> SELECT a.id",
    syntax_limits(),
  ).unwrap()
  assert_true(
    compile_query_script(
      incomplete_mean,
      { ..fixture_context(), inputs: [], },
      construction_limits(),
    )
    is Err(InvalidQuery),
  )
  let unknown = @query.parse_query_script(
    prefix +
    "DATA normalized = FROM later |> normalize_graph(); FROM GRAPH normalized |> MATCH WALK (a:Node) |> SELECT a.id",
    syntax_limits(),
  ).unwrap()
  assert_true(
    exact_unresolved_relation(
      compile_query_script(
        unknown,
        { ..fixture_context(), inputs: [], },
        construction_limits(),
      ),
      [("later", false)],
    ),
  )
}

///|
fn traversal_paths_source() -> String {
  "DATA n = SELECT 1 AS node_key; DATA g = PROPERTY GRAPH (NODE TABLES (n AS N KEY (node_key) LABEL Node NO PROPERTIES)); DATA seeds = FROM g |> node_rows() |> SELECT id AS element; FROM g |> traverse(start: {from: seeds, id: 'element'}, direction: 'out', min_hops: 0, max_hops: 1, path_mode: 'trail', emit: 'paths', max_output_rows: 10) |> SELECT start_id, end_id, hop_count, node_ids, edge_ids"
}

///|
fn traversal_paths_expected() -> @program.Program {
  // Independently authored complete Program and ordered path fields. No
  // lowering output or runtime sample supplies this oracle.
  @program.parse(
    (
      #|{"version":"actql/0.1","id":"fixture.query_pair","stages":[{"id":"main","inputs":{},"steps":[{"values":{"schema":{"aql_source_free_unit":{"type":"boolean","nullable":false}},"rows":[{"aql_source_free_unit":true}]},"as":"aql_script_seed_1"},{"from":"aql_script_seed_1","derive":{"aql_query_expr_0":{"literal":1}}},{"select":[{"node_key":"aql_query_expr_0"}],"as":"aql_data_0"},{"graph":{"version":"actql-graph-constructor/0.1","nodes":[{"name":"N","from":"aql_data_0","key":["node_key"],"labels":[{"name":"Node","properties":{"mode":"no_properties"}}]}],"edges":[]},"as":"aql_data_2"},{"from":"aql_data_2","node_rows":true,"as":"aql_sga_4"},{"from":"aql_sga_4","select":[{"element":"id"}],"as":"aql_data_3"},{"from":"aql_data_2","traverse":{"start":{"from":"aql_data_3","id":"element"},"direction":"out","min_hops":0,"max_hops":1,"path_mode":"trail","emit":"paths","max_output_rows":10},"as":"aql_sga_5"},{"from":"aql_sga_5","select":["start_id","end_id","hop_count","node_ids","edge_ids"],"as":"aql_script_result"}],"results":{"rows":{"from":"aql_script_result","fields":["start_id","end_id","hop_count","node_ids","edge_ids"]}}}],"results":{"answer":{"from":{"stage":"main","result":"rows"}}}}
    ),
    construction_limits().program,
    format=Json,
  ).unwrap()
}

///|
test "Graph traversal path independent Program passes the ordinary checker" {
  match
    @check.check_parsed_with_evidence(
      traversal_paths_expected(),
      graph_rows_environment(),
      None,
      [],
      graph_rows_check_limits(),
    ) {
    Checked(_) => ()
    Rejected(diagnostic) => graph_rows_rejected(diagnostic)
    NeedsInputs(_) => fail("DATA selector reuses a producer")
  }
}

///|
test "Graph traversal path source retains an independent complete Program" {
  let actual = match
    compile_query_script(
      @query.parse_query_script(traversal_paths_source(), syntax_limits()).unwrap(),
      { ..fixture_context(), inputs: [], },
      construction_limits(),
    ) {
    Ok(program) => program
    Err(UnsupportedGraph) => fail("UnsupportedGraph")
    Err(_) => fail("unexpected lowering refusal")
  }
  assert_eq(semantic(actual), semantic(traversal_paths_expected()))
}

///|
test "Graph traversal path DATA preserves declared arguments and current column scope" {
  let source = traversal_paths_source()
    .replace(old="DATA seeds", new="DATA `seed set`")
    .replace(old="from: seeds", new="from: `seed set`")
    .replace(old="FROM g |> traverse", new="DATA visited = FROM g |> traverse") +
    "; FROM visited |> WHERE hop_count >= 0 |> SELECT edge_ids, node_ids, hop_count |> ORDER BY hop_count"
  let program = compile_with_set(source)
  let body = semantic(program)
  assert_eq(body.split("\"traverse\":").length(), 2)
  assert_true(body.contains("\"max_output_rows\":10"))
  assert_true(
    body.contains("\"fields\":[\"edge_ids\",\"node_ids\",\"hop_count\"]"),
  )
  match
    @check.check_parsed_with_evidence(
      program,
      graph_rows_environment(),
      None,
      [],
      graph_rows_check_limits(),
    ) {
    Checked(_) => ()
    Rejected(diagnostic) => graph_rows_rejected(diagnostic)
    NeedsInputs(_) => fail("A bound path producer is not acquired again")
  }
}

///|
test "Graph traversal path fields cannot be confused with node emission fields" {
  // Literal UTF-8 ranges belong to the final SELECT, not an earlier Graph field.
  for (field, end) in [("depth", 350), ("node_id", 352)] {
    let source = traversal_paths_source().replace(
      old="SELECT start_id, end_id, hop_count, node_ids, edge_ids",
      new="SELECT " + field,
    )
    let result = compile_query_script(
      @query.parse_query_script(source, syntax_limits()).unwrap(),
      { ..fixture_context(), inputs: [], },
      construction_limits(),
    )
    guard result
      is Err(
        Expression(
          { issue: @expression.UnknownReference, origin: Some(origin), }
        )
      ) else {
      fail("path output must reject node-only field: " + field)
    }
    assert_eq(@origin.kind(origin), @origin.Authored)
    let span = @origin.span(origin)
    assert_eq(span.start_byte, 345)
    assert_eq(span.end_byte, end)
  }
}

///|
test "Graph traversal path emission remains explicit and static" {
  for value in ["'invented'", "@emission"] {
    let source = traversal_paths_source().replace(old="'paths'", new=value)
    assert_true(
      compile_query_script(
        @query.parse_query_script(source, syntax_limits()).unwrap(),
        { ..fixture_context(), inputs: [], },
        construction_limits(),
      )
      is Err(UnsupportedGraph),
      msg=value,
    )
  }
  let omitted = traversal_paths_source().replace(old=", emit: 'paths'", new="")
  assert_true(
    compile_query_script(
      @query.parse_query_script(omitted, syntax_limits()).unwrap(),
      { ..fixture_context(), inputs: [], },
      construction_limits(),
    )
    is Err(UnsupportedGraph),
  )
}

///|
test "Graph traversal path preserves malformed arguments for common refusal" {
  for
    (before, after) in [
      ("id: 'element'", "id: 'missing'"),
      ("max_hops: 1", "max_hops: 0"),
      ("path_mode: 'trail'", "path_mode: 'invented'"),
      ("max_output_rows: 10", "max_output_rows: 10, extra: true"),
    ] {
    let program = compile_with_set(
      traversal_paths_source().replace(old=before, new=after),
    )
    assert_true(
      @check.check_parsed_with_evidence(
        program,
        graph_rows_environment(),
        None,
        [],
        graph_rows_check_limits(),
      )
      is Rejected(_),
      msg=after,
    )
  }
}

///|
fn matched_traversal_path_source() -> String {
  traversal_paths_source().replace(
    old="node_rows()",
    new="match_nodes(definition: 'N', bindings: {identity: 'id'}, where: {literal: true}, fields: ['id'])",
  )
}

///|
test "named Graph match feeds traversal paths in one checked source Program" {
  let actual = compile_with_set(matched_traversal_path_source())
  // The existing independent path Program with an explicitly authored match
  // step supplies the oracle; compiler output does not supply expectations.
  let expected = @program.parse(
    (
      #|{"version":"actql/0.1","id":"fixture.query_pair","stages":[{"id":"main","inputs":{},"steps":[{"values":{"schema":{"aql_source_free_unit":{"type":"boolean","nullable":false}},"rows":[{"aql_source_free_unit":true}]},"as":"aql_script_seed_1"},{"from":"aql_script_seed_1","derive":{"aql_query_expr_0":{"literal":1}}},{"select":[{"node_key":"aql_query_expr_0"}],"as":"aql_data_0"},{"graph":{"version":"actql-graph-constructor/0.1","nodes":[{"name":"N","from":"aql_data_0","key":["node_key"],"labels":[{"name":"Node","properties":{"mode":"no_properties"}}]}],"edges":[]},"as":"aql_data_2"},{"from":"aql_data_2","match_nodes":{"definition":"N","bindings":{"identity":"id"},"where":{"literal":true},"fields":["id"]},"as":"aql_sga_4"},{"from":"aql_sga_4","select":[{"element":"id"}],"as":"aql_data_3"},{"from":"aql_data_2","traverse":{"start":{"from":"aql_data_3","id":"element"},"direction":"out","min_hops":0,"max_hops":1,"path_mode":"trail","emit":"paths","max_output_rows":10},"as":"aql_sga_5"},{"from":"aql_sga_5","select":["start_id","end_id","hop_count","node_ids","edge_ids"],"as":"aql_script_result"}],"results":{"rows":{"from":"aql_script_result","fields":["start_id","end_id","hop_count","node_ids","edge_ids"]}}}],"results":{"answer":{"from":{"stage":"main","result":"rows"}}}}
    ),
    construction_limits().program,
    format=Json,
  ).unwrap()
  assert_eq(semantic(actual), semantic(expected))
  for program in [expected, actual] {
    match
      @check.check_parsed_with_evidence(
        program,
        graph_rows_environment(),
        None,
        [],
        graph_rows_check_limits(),
      ) {
      Checked(_) => ()
      Rejected(diagnostic) => graph_rows_rejected(diagnostic)
      NeedsInputs(_) => fail("The matched selector reuses the same Graph")
    }
  }
}

///|
test "combined match and path source preserves independent refusal boundaries" {
  let missing_selector = compile_with_set(
    matched_traversal_path_source().replace(
      old="id: 'element'",
      new="id: 'missing'",
    ),
  )
  assert_true(
    @check.check_parsed_with_evidence(
      missing_selector,
      graph_rows_environment(),
      None,
      [],
      graph_rows_check_limits(),
    )
    is Rejected(_),
  )
  let node_only_field = matched_traversal_path_source().replace(
    old="SELECT start_id, end_id, hop_count, node_ids, edge_ids",
    new="SELECT depth",
  )
  let result = compile_query_script(
    @query.parse_query_script(node_only_field, syntax_limits()).unwrap(),
    { ..fixture_context(), inputs: [], },
    construction_limits(),
  )
  guard result
    is Err(
      Expression({ issue: @expression.UnknownReference, origin: Some(origin), })
    ) else {
    fail("matched path output must reject the node-only depth field")
  }
  assert_eq(@origin.kind(origin), @origin.Authored)
  let span = @origin.span(origin)
  assert_eq(span.start_byte, 430)
  assert_eq(span.end_byte, 435)
}
